contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public payable {
        address ownerBefore = c.owner();
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        address ownerAfter = c.owner();
        assert(ownerAfter == ownerBefore && reverted == (ownerBefore != address(this)));
    }
    receive() external payable {}
}
